    'creator.leaderboards.templateLead': 'The template includes a ten-click mini-game, editable source, the SDK, and leaderboard configuration. It supports Web games and the same game running in Cursor, VS Code, or Harness.',
    'creator.leaderboards.download': 'Download leaderboard template',
    'creator.leaderboards.guide': 'Integration guide ↗',
    'creator.leaderboards.step1': 'Extract the template and update the game plus the metrics, ranking direction, and leaderboard title in platform.json.',
    'creator.leaderboards.step2': 'Start a run through the SDK and submit the score when it ends. Reuse the same run and payload when retrying a failed request.',
    'creator.leaderboards.step3': 'Package the files as a ZIP and upload it to the work. After validation and publishing, the leaderboard appears on its detail page.',
    'creator.leaderboards.casual': 'Casual leaderboard',
    'creator.leaderboards.casualBody': 'A practical starting point for scores, moves, or completion time. The client reports results; the platform validates format, bounds, and submission rate and labels it as casual.',
    'creator.leaderboards.replay': 'Rule replay verification',
    'creator.leaderboards.replayBody': 'A 4×4 2048 rule template is currently available. The platform issues a seed and recomputes the score from moves. Scoring or algorithm changes require a new ruleset version.',
    'creator.leaderboards.immutable': 'A ruleset version cannot be overwritten',
    'creator.leaderboards.limits': 'Each version supports up to three leaderboards and four integer metrics per leaderboard, with all-time and Beijing-time daily periods. Preview results never enter public leaderboards.',
    'creator.multiplayer.title': 'Multiplayer developer center',
    'creator.multiplayer.lead': 'Start from the official two-player template, use the real SDK for rooms, authoritative commands, private views, reconnects, and match endings, then export a package for platform review.',
