    'creator.multiplayer.testTitle': 'Two-session testing and machine reports',
    'creator.multiplayer.testBody': 'Creator Doctor reuses the production ZIP Validator and checks version boundaries, obvious token references, rule exports, identity, determinism, rejection of out-of-turn players, duplicate processing, secret sentinels, public events, resignation, and timeout endings. Real reconnects require two independent account windows; Doctor never fabricates a pass.',
